"""Thin HTTP client for pushing findings into secman via POST /api/vulnerabilities/cli-add.

Mirrors secman's own CLI (CliHttpClient.authenticate in the secman repo): the
login response carries no token in its JSON body — the JWT only appears in the
Set-Cookie: secman_auth=<jwt> response header. Subsequent requests send it as
a standard Authorization: Bearer header (Micronaut's bearer-token reader stays
active alongside cookie auth on the secman backend).
"""

from __future__ import annotations

import requests
from tenacity import retry, retry_if_exception_type, stop_after_attempt, wait_exponential

from . import dryrun

_TIMEOUT_S = 30
_RETRY = dict(
    stop=stop_after_attempt(3),
    wait=wait_exponential(multiplier=1, min=2, max=20),
    retry=retry_if_exception_type(requests.exceptions.ConnectionError),
    reraise=True,
)


class SecmanPushError(Exception):
    """Raised on login failure or a rejected cli-add call."""


def _extract_cookie_token(set_cookie_header: str, cookie_name: str = "secman_auth") -> str | None:
    for part in set_cookie_header.split(";"):
        part = part.strip()
        if part.startswith(f"{cookie_name}="):
            return part[len(f"{cookie_name}="):]
    return None


@retry(**_RETRY)
def login(base_url: str, username: str, password: str) -> str:
    """POST /api/auth/login, return the JWT extracted from Set-Cookie."""
    dryrun.guard("authenticate against secman")
    resp = requests.post(
        f"{base_url}/api/auth/login",
        json={"username": username, "password": password},
        timeout=_TIMEOUT_S,
    )
    if resp.status_code != 200:
        raise SecmanPushError(f"secman login failed: {resp.status_code} {resp.text[:300]}")

    set_cookie = resp.headers.get("Set-Cookie", "")
    token = _extract_cookie_token(set_cookie)
    if not token:
        raise SecmanPushError("secman login succeeded but no auth token found in Set-Cookie response header")
    return token


@retry(**_RETRY)
def push_vulnerability(
    base_url: str,
    token: str,
    *,
    hostname: str,
    cve: str,
    criticality: str,
    days_open: int,
) -> dict:
    """POST /api/vulnerabilities/cli-add with Authorization: Bearer {token}."""
    dryrun.guard(f"push {cve} for {hostname} to secman")
    resp = requests.post(
        f"{base_url}/api/vulnerabilities/cli-add",
        json={"hostname": hostname, "cve": cve, "criticality": criticality, "daysOpen": days_open},
        headers={"Authorization": f"Bearer {token}"},
        timeout=_TIMEOUT_S,
    )
    if resp.status_code != 200:
        raise SecmanPushError(f"cli-add failed: {resp.status_code} {resp.text[:300]}")
    return resp.json()
"""Push High/Critical findings from the state store into secman.

Shared by the `push-to-secman` command (which pushes every record in the state
DB) and by `scan` / `run` with `--push-to-secman` (which push only the repos
that invocation reviewed). The HTTP details live in `secman_client`.
"""

from __future__ import annotations

import os
from datetime import datetime, timezone

import typer

from . import secman_client
from .findings import fingerprint
from .issues import _FIELD_MAX, _truncate


def resolve_credentials(
    url: str | None, username: str | None, password: str | None
) -> tuple[str | None, str | None, str | None]:
    """Explicit value first, then SECMAN_URL / SECMAN_USERNAME / SECMAN_PASSWORD."""
    return (
        url or os.environ.get("SECMAN_URL") or None,
        username or os.environ.get("SECMAN_USERNAME") or None,
        password or os.environ.get("SECMAN_PASSWORD") or None,
    )


def _cve_and_days_open(store, owner: str, repo: str, row) -> tuple[str, int]:
    class _RowFinding:
        severity = type("S", (), {"value": row["severity"]})()
        category = row["category"]
        title = row["title"]
        file_path = row["file_path"]

    fp = fingerprint(_RowFinding())
    issue = store.find_issue(owner, repo, fp)
    days_open = 0
    if issue is not None:
        first_seen = datetime.fromisoformat(issue.first_seen_at)
        days_open = max(0, (datetime.now(timezone.utc) - first_seen).days)
    # row["category"] is LLM output about untrusted repository content (see
    # issues.py's _issue_body for the same concern on the GitHub issue path);
    # cap it before it becomes part of the identifier pushed to secman's
    # vulnerability tracker.
    cve = f"SECSCAN:{_truncate(row['category'], _FIELD_MAX) or 'FINDING'}:{fp[:12]}"
    return cve, days_open


def push_records(
    store,
    records,
    *,
    url: str | None,
    username: str | None,
    password: str | None,
    dry_run: bool,
) -> tuple[int, int]:
    """Push each record's High/Critical findings; return (pushed, failed).

    Logs in once. A login failure raises SecmanPushError for the caller to act on;
    a single rejected finding is reported and counted, and the rest still push.
    A dry run makes no calls at all and needs no credentials.
    """
    token = None
    if not dry_run:
        token = secman_client.login(url, username, password)

    pushed = failed = 0
    for rec in records:
        for row in store.get_findings(rec.owner, rec.repo):
            if row["severity"] not in ("critical", "high"):
                continue

            cve, days_open = _cve_and_days_open(store, rec.owner, rec.repo, row)
            hostname = rec.full_name

            if dry_run:
                typer.echo(f"would push {hostname} {cve} {row['severity'].upper()}")
                pushed += 1
                continue

            try:
                secman_client.push_vulnerability(
                    url, token,
                    hostname=hostname, cve=cve,
                    criticality=row["severity"].upper(), days_open=days_open,
                )
                pushed += 1
            except secman_client.SecmanPushError as exc:
                typer.echo(f"failed: {hostname} {cve}: {exc}", err=True)
                failed += 1

    return pushed, failed
    Port is deliberately excluded — an asset is a machine, and two services on
    one host belong to the same inventory entry. The port still participates in
    the finding id, so findings on :8080 and :443 stay distinct.
    """
    if override:
        return override
    host = urlparse(url).hostname
    if not host:
        raise SecmanError(f"cannot derive a SecMan asset name from {url!r}")
    return host.lower()


def vulnerability_id(url: str, category: str, prefix: str = DEFAULT_ID_PREFIX) -> str:
    """A stable id for "this category of exposure, on this page".

    Derived from host, port, path, query and category — never from the model's
    wording, which changes between runs and would mint a new id every scan.
    """
    parsed = urlparse(url)
    host = (parsed.hostname or "").lower()
    port = f":{parsed.port}" if parsed.port else ""
    path = parsed.path or "/"
    query = f"?{parsed.query}" if parsed.query else ""
    slug = re.sub(r"[^A-Z0-9]+", "-", (category or "finding").upper()).strip("-") or "FINDING"
    digest = hashlib.sha256(
        f"{host}{port}{path}{query}|{(category or '').strip().lower()}".encode("utf-8")
    ).hexdigest()[:10]
    return f"{prefix}-{slug}-{digest}".upper()


@dataclass(frozen=True)
class UploadItem:
    """One finding, already shaped the way SecMan wants it."""

    hostname: str
    vulnerability_id: str
    criticality: str
    severity: Severity
    url: str
    category: str
    title: str

    @property
    def key(self) -> tuple[str, str]:
        return (self.hostname.lower(), self.vulnerability_id)

    def payload(self, owner: str = DEFAULT_OWNER) -> dict[str, Any]:
        """The request body for ``/api/vulnerabilities/cli-add`` and ``add_vulnerability``."""
        return {
            "hostname": self.hostname,
            "cve": self.vulnerability_id,
            "criticality": self.criticality,
            "daysOpen": 0,
            "owner": owner,
        }


#: Terminal states an item can end in. ``planned`` only occurs in a dry run and
#: means "would have been written"; ``skipped`` always means "SecMan has it".
UPLOAD_STATUSES = ("created", "updated", "planned", "skipped", "failed")


@dataclass
class UploadOutcome:
    """What happened to one item — one of :data:`UPLOAD_STATUSES`."""

    item: UploadItem
    status: str
    detail: str = ""

    @property
    def written(self) -> bool:
        return self.status in ("created", "updated")


@dataclass
     * User Story 2: Add vulnerability with auto-created asset (P2)
     */
    @Post("/api/vulnerabilities/cli-add")
    @Secured("ADMIN", "VULN")
    open fun addVulnerabilityFromCli(
        @Valid @Body request: AddVulnerabilityRequestDto,
        authentication: Authentication
    ): HttpResponse<*> {
        return try {
            log.info("CLI add-vulnerability requested by user: {} - hostname: {}, cve: {}",
