class _HttpxBacked(SecmanUploader):
    """Shared httpx plumbing: client construction and retry policy."""

    def __init__(
        self,
        base_url: str,
        *,
        timeout: float = DEFAULT_TIMEOUT_S,
        verify: bool = True,
        headers: dict[str, str] | None = None,
        client: Any = None,
        max_retries: int = 2,
        retry_backoff: float = 1.0,
    ) -> None:
        self.base_url = base_url.rstrip("/")
        self.max_retries = max(0, max_retries)
        self.retry_backoff = retry_backoff
        if client is not None:
            self._client = client
        else:
            import httpx

            self._client = httpx.Client(
                base_url=self.base_url,
                timeout=httpx.Timeout(timeout),
                verify=verify,
                follow_redirects=True,
                headers=headers or {},
            )

    def close(self) -> None:
        closer = getattr(self._client, "close", None)
        if closer:
            closer()

    def _send(self, method: str, path: str, **kwargs: Any):
        """One request with retries on transient statuses and transport errors."""
        import httpx

        delay = self.retry_backoff
        attempt = 0
        while True:
            try:
                response = self._client.request(method, path, **kwargs)
            except httpx.HTTPError as exc:
                if attempt >= self.max_retries:
                    raise SecmanError(f"{method} {path} failed: {exc}") from exc
                attempt += 1
                time.sleep(delay)
                delay *= 2
