            if (timed) params + ("now" to Instant.now()) else params)
        val stale = "timestampadd(hour, c.staleAfterHours, coalesce(x.lastSuccessfulScanAt, x.createdAt)) < :now"
        val scannerScope = if (assetIds == null) "1 = 1" else
            "EXISTS (SELECT s.id FROM IntegrationSubject s WHERE s.scannerId = x.id AND s.assetId IN :assets)"
        val findingScope = if (assetIds == null) "1 = 1" else "s.assetId IN :assets"
        return IntegrationSummaryDto(
            repository.count("FROM IntegrationScanner x", scannerScope, params), count(),
            count("x.lastStatus = 'SUCCESS' AND NOT ($stale)", true), count("x.lastStatus IN ('FAILED', 'PARTIAL')"),
            count("x.lastScanAt IS NULL"), count("c.enabled = true AND $stale", true),
            repository.count("FROM IntegrationFinding x, IntegrationSubject s", "x.subjectId = s.id AND x.state = 'OPEN' AND $findingScope", params)
        )
    }

    private fun authorizedFinding(id: Long, auth: Authentication): IntegrationFinding {
        val finding = repository.find(IntegrationFinding::class.java, id) ?: access.notFound()
        val subject = repository.find(IntegrationSubject::class.java, finding.subjectId) ?: access.notFound()
        access.requireAsset(subject.assetId, auth)
