    ) async throws -> RelayBinding {
        struct Body: Encodable {
            let provider: String
            let idToken: String
            let nonce: String
            let publicKey: String
            let signature: String
            let deviceName: String
        }
        return try await send(
            path: "/api/v1/auth/oidc",
            method: "POST",
            body: Body(
