/**
 * Vulnerability entity representing a security vulnerability discovered during a scan.
 *
 * Linked to an Asset entity via ManyToOne relationship.
 * Feature 048: Uses transactional replace pattern - each import deletes existing vulnerabilities
 * for an asset and inserts current ones, ensuring only the latest state is stored.
 *
 * @property id Unique identifier
 * @property asset Asset this vulnerability affects (required)
 * @property vulnerabilityId CVE or vulnerability identifier (e.g., "CVE-2016-2183")
 * @property cvssSeverity CVSS severity level (e.g., "High", "Critical", "Medium", "Low", "Informational")
 * @property vulnerableProductVersions Affected product/version information
 * @property daysOpen Text representation of days open at last import (e.g., "58 days") - display only, may be stale
 * @property scanTimestamp Discovery date as reported by the most recent import (refreshed each import)
 * @property firstSeenAt Earliest known detection of this (asset, CVE, product) — preserved across re-imports.
 *                       Anchor for SLA/overdue calculations and "days open" display. Falls back to scanTimestamp on first insert.
 * @property importTimestamp When this data was imported (same for all vulns in batch, for "current" query)
 * @property patchPublicationDate When a fix became available (optional, from CrowdStrike API). Prefers a
 *                                remediation/vendor release date; falls back to the CVE publication date.
 * @property cvePublishedDate When the CVE itself was disclosed (optional). Never an SLA anchor — display only.
 * @property createdAt When the record was first created in the database (auto-generated)
 */
@Entity
@Table(
    name = "vulnerability",
    indexes = [
        // Composite (asset_id, scan_timestamp): serves WHERE asset_id = ? for asset-scoped queries
        // (via MariaDB's leftmost-prefix rule) AND threshold-date overdue queries combined with
        // asset filters. Replaces the standalone idx_vulnerability_asset that was dropped in V217.
        Index(name = "idx_vulnerability_asset_scan", columnList = "asset_id,scan_timestamp"),
        Index(name = "idx_vulnerability_severity", columnList = "cvss_severity"),                  // MCP severity filter
        Index(name = "idx_vulnerability_cve", columnList = "vulnerability_id"),                    // CVE ID lookups (MCP search)
        Index(name = "idx_vulnerability_asset_cve", columnList = "asset_id,vulnerability_id"),     // Duplicate detection
        Index(name = "idx_vulnerability_scan_timestamp", columnList = "scan_timestamp"),           // Unscoped date-range filter (MCP)
        Index(name = "idx_vulnerability_import_ts", columnList = "asset_id,import_timestamp"),     // "Current vulnerabilities" DENSE_RANK PARTITION
        // Serves the admin/user "current vulnerabilities" not_excepted view:
        //   WHERE excepted = 0 ORDER BY import_timestamp DESC, asset_name ASC, vulnerability_id ASC
        // filesort-free. The Flyway DDL (V236) creates this with import_timestamp DESC — JPA @Index
        // has no direction syntax, so **Flyway is authoritative for the column direction**; this
        // annotation exists only so hbm2ddl.auto=update sees the name already present and does NOT
        // recreate an ASC-only variant. Do not "fix" the apparent mismatch. See V236 header.
        Index(name = "idx_vulnerability_excepted_sort", columnList = "excepted,import_timestamp,asset_name,vulnerability_id")
        // NOTE: idx_vulnerability_asset, idx_vulnerability_sort_order, and
        // idx_vulnerability_product were removed in V217 because they served no read path
        // (prefix-redundancy, cross-table ORDER BY filesort, disqualified LIKE patterns
        // respectively) while contributing materially to deadlock contention and write
        // amplification during concurrent CrowdStrike imports. See V217 header for the
        // full audit rationale.
    ]
)
