     * [com.secman.service.ProductClassificationService], never from CrowdStrike directly:
     * Spotlight exposes no path and no installer flag.
     *
     * Same safe direction as [excepted] — the default UNKNOWN is treated as visible, and only
     * an explicit INSTALLER_ARTIFACT hides a row.
     */
    @Enumerated(EnumType.STRING)
    @Column(name = "product_class", nullable = false, length = 20)
    var productClass: ProductClass = ProductClass.UNKNOWN,

    /**
     * Denormalized copy of `asset.name`, set at insert (see [onCreate]). Lets the default sort
     * `import_timestamp DESC, asset_name ASC, vulnerability_id ASC` be served single-table by
     * `idx_vulnerability_excepted_sort` without a cross-table filesort. Affects sort order only,
     * never visibility, so staleness after a bare asset rename is cosmetic (CrowdStrike rows
     * self-heal each import).
     */
    @Column(name = "asset_name", length = 255)
    var assetName: String? = null,

    @Column(name = "created_at", updatable = false)
    var createdAt: LocalDateTime? = null
) {
